1	//! SSH-over-Iroh transport plus content-addressed recording transfer.
2	//!
3	//! Git and SSH remain completely unaware of Iroh. The desktop accepts Iroh
4	//! streams and forwards them to the embedded SSH server on loopback. The phone
5	//! exposes a loopback TCP listener and forwards each libgit2 SSH connection to
6	//! the desktop's Iroh endpoint. Recording bytes are provided by `iroh-blobs`;
7	//! the custom Type stream carries only a small path/hash offer and receipt.
8	
9	use crate::{app_data_dir, AppEnv};
10	use iroh::{
11	    endpoint::{presets, Connection},
12	    protocol::{AcceptError, ProtocolHandler, Router},
13	    Endpoint, EndpointAddr, SecretKey,
14	};
15	use iroh_blobs::{
16	    api::{Store as BlobStore, TempTag},
17	    store::fs::FsStore,
18	    ticket::BlobTicket,
19	    BlobFormat, BlobsProtocol,
20	};
21	use iroh_tickets::endpoint::EndpointTicket;
22	use rand_core::{OsRng, RngCore};
23	use serde::{Deserialize, Serialize};
24	use std::{
25	    fs,
26	    path::{Path, PathBuf},
27	    str::FromStr,
28	    sync::{Arc, Mutex},
29	    time::Duration,
30	};
31	use subtle::ConstantTimeEq;
32	use tokio::io::{AsyncReadExt, AsyncWriteExt};
33	use uuid::Uuid;
34	
35	const IROH_ALPN: &[u8] = b"type/ssh-tunnel/1";
36	const IROH_SSH_HANDSHAKE: &[u8; 5] = b"type1";
37	const IROH_AUDIO_HANDSHAKE: &[u8; 5] = b"aud02";
38	const IROH_PAIR_HANDSHAKE: &[u8; 5] = b"pair1";
39	const IROH_ONLINE_TIMEOUT: Duration = Duration::from_secs(5);
40	const MAX_AUDIO_HEADER_BYTES: usize = 16 * 1024;
41	const MAX_AUDIO_BYTES: u64 = 2 * 1024 * 1024 * 1024;
42	const MAX_PAIRING_TOKEN_BYTES: usize = 128;
43	const IROH_ENDPOINTS_FILE: &str = "iroh_endpoints.json";
44	pub const IROH_CLIENT_PROXY_PORT: u16 = 19_418;
45	
46	/// Arguments supplied by the mobile shell after scanning a pairing QR.
47	#[derive(Clone, Deserialize)]
48	pub struct StartIrohClientArgs {
49	    pub ticket: String,
50	    pub remote_url: String,
51	}
52	
53	/// Loopback connection details returned to the mobile Git adapter.
54	#[derive(Clone, Serialize)]
55	pub struct IrohClientStatus {
56	    pub running: bool,
57	    pub local_port: u16,
58	    pub local_remote_url: String,
59	    pub endpoint_id: String,
60	}
61	
62	#[derive(Clone, Serialize)]
63	pub struct IrohAudioArchiveResult {
64	    pub scanned: usize,
65	    pub uploaded: usize,
66	    pub already_archived: usize,
67	}
68	
69	#[derive(Deserialize, Serialize)]
70	struct AudioUploadHeader {
71	    audio_path: String,
72	    sha256: String,
73	    blake3: String,
74	    byte_length: u64,
75	    blob_ticket: String,
76	}
77	
78	#[derive(Deserialize, Serialize)]
79	struct AudioUploadResponse {
80	    ok: bool,
81	    error: Option<String>,
82	    sha256: Option<String>,
83	    blake3: Option<String>,
84	    byte_length: Option<u64>,
85	}
86	
87	#[derive(Clone, Debug)]
88	struct IrohServerAuth {
89	    pairing_token: Arc<Mutex<String>>,
90	    endpoints_path: PathBuf,
91	    endpoints_lock: Arc<Mutex<()>>,
92	}
93	
94	impl IrohServerAuth {
95	    fn is_authorized(&self, endpoint_id: &str) -> bool {
96	        let Ok(_guard) = self.endpoints_lock.lock() else {
97	            return false;
98	        };
99	        load_authorized_iroh_endpoints(&self.endpoints_path)
100	            .iter()
101	            .any(|allowed| allowed == endpoint_id)
102	    }
103	
104	    fn authorize_with_pairing_token(
105	        &self,
106	        endpoint_id: &str,
107	        supplied_token: &str,
108	    ) -> Result<(), String> {
109	        if self.is_authorized(endpoint_id) {
110	            return Ok(());
111	        }
112	        let current = self
113	            .pairing_token
114	            .lock()
115	            .map_err(|_| "The direct-sync pairing state is unavailable.".to_string())?;
116	        if current.is_empty()
117	            || supplied_token.len() != current.len()
118	            || !bool::from(supplied_token.as_bytes().ct_eq(current.as_bytes()))
119	        {
120	            return Err("This phone is not paired for Iroh audio sync. Scan the QR again.".into());
121	        }
122	        drop(current);
123	
124	        let _guard = self
125	            .endpoints_lock
126	            .lock()
127	            .map_err(|_| "The Iroh paired-device store is unavailable.".to_string())?;
128	        register_authorized_iroh_endpoint(&self.endpoints_path, endpoint_id)
129	    }
130	}
131	
132	/// Desktop-side endpoint owned by the embedded local-sync daemon.
133	pub struct IrohServerHandle {
134	    runtime: tokio::runtime::Runtime,
135	    router: Router,
136	    ticket: String,
137	    endpoint_id: String,
138	}
139	
140	impl IrohServerHandle {
141	    pub fn ticket(&self) -> &str {
142	        &self.ticket
143	    }
144	
145	    pub fn endpoint_id(&self) -> &str {
146	        &self.endpoint_id
147	    }
148	
149	    pub fn stop(self) {
150	        let Self {
151	            runtime, router, ..
152	        } = self;
153	        let _ = runtime.block_on(router.shutdown());
154	        runtime.shutdown_background();
155	    }
156	}
157	
158	struct IrohClientHandle {
159	    runtime: tokio::runtime::Runtime,
160	    router: Router,
161	    blobs: BlobStore,
162	    remote_addr: EndpointAddr,
163	    pairing_token: Option<String>,
164	    ticket: String,
165	    endpoint_id: String,
166	    local_port: u16,
167	}
168	
169	impl IrohClientHandle {
170	    fn status_for_remote(&self, remote_url: &str) -> Result<IrohClientStatus, String> {
171	        Ok(IrohClientStatus {
172	            running: true,
173	            local_port: self.local_port,
174	            local_remote_url: rewrite_ssh_remote_to_loopback(remote_url, self.local_port)?,
175	            endpoint_id: self.endpoint_id.clone(),
176	        })
177	    }
178	
179	    fn stop(self) {
180	        let Self {
181	            runtime, router, ..
182	        } = self;
183	        let _ = runtime.block_on(router.shutdown());
184	        runtime.shutdown_background();
185	    }
186	}
187	
188	#[derive(Clone, Debug)]
189	struct TypeSyncProtocol {
190	    target_port: u16,
191	    repo_root: PathBuf,
192	    endpoint: Endpoint,
193	    blobs: BlobStore,
194	    auth: IrohServerAuth,
195	}
196	
197	impl ProtocolHandler for TypeSyncProtocol {
198	    async fn accept(&self, connection: Connection) -> Result<(), AcceptError> {
199	        handle_iroh_connection(
200	            connection,
201	            self.target_port,
202	            self.repo_root.clone(),
203	            self.endpoint.clone(),
204	            self.blobs.clone(),
205	            self.auth.clone(),
206	        )
207	        .await
208	        .map_err(|error| AcceptError::from_err(std::io::Error::other(error)))
209	    }
210	}
211	
212	static CLIENT: Mutex<Option<IrohClientHandle>> = Mutex::new(None);
213	
214	/// Start the desktop endpoint and forward accepted streams to the SSH server.
215	pub fn start_iroh_sync_server(
216	    app: &AppEnv,
217	    target_port: u16,
218	    repo_root: PathBuf,
219	    pairing_token: Arc<Mutex<String>>,
220	) -> Result<IrohServerHandle, String> {
221	    let secret = load_or_create_secret(app, "server.key")?;
222	    // The post-0.35 blob store is a rewrite with a different on-disk format.
223	    // Keep its cache isolated so an experimental upgrade cannot corrupt an
224	    // older store. Both are disposable caches; durable audio lives in notes.
225	    let blobs_path = blob_store_path(app, "server-blobs-v103")?;
226	    let auth = IrohServerAuth {
227	        pairing_token,
228	        endpoints_path: iroh_endpoints_path(app)?,
229	        endpoints_lock: Arc::new(Mutex::new(())),
230	    };
231	    let runtime = runtime("Iroh sync server")?;
232	    let router = runtime.block_on(async {
233	        let endpoint = Endpoint::builder(presets::N0)
234	            .secret_key(secret)
235	            .bind()
236	            .await
237	            .map_err(|error| format!("Failed to bind the Iroh sync endpoint: {error}"))?;
238	        let store = FsStore::load(blobs_path)
239	            .await
240	            .map_err(|error| format!("Failed to open the desktop Iroh blob store: {error}"))?;
241	        let store: BlobStore = store.into();
242	        let blobs = BlobsProtocol::new(&store, None);
243	        let sync = TypeSyncProtocol {
244	            target_port,
245	            repo_root,
246	            endpoint: endpoint.clone(),
247	            blobs: store,
248	            auth,
249	        };
250	        Ok::<Router, String>(
251	            Router::builder(endpoint)
252	                .accept(IROH_ALPN, sync)
253	                .accept(iroh_blobs::ALPN, blobs)
254	                .spawn(),
255	        )
256	    })?;
257	
258	    // A relay address makes the QR useful across networks. Offline startup is
259	    // still allowed: the ticket can retain direct addresses for LAN testing.
260	    //
261	    // `tokio::time::timeout(...)` must be constructed *inside* the async block
262	    // below, not passed as a bare argument to `block_on` — argument evaluation
263	    // happens on the calling thread before `block_on` enters the runtime, so a
264	    // bare-argument `Timeout` panics with "there is no reactor running".
265	    runtime
266	        .block_on(async {
267	            tokio::time::timeout(IROH_ONLINE_TIMEOUT, router.endpoint().online()).await
268	        })
269	        .map_err(|_| "Iroh did not discover a relay or direct address in time.".to_string())?;
270	    let ticket = EndpointTicket::new(router.endpoint().addr()).to_string();
271	    let endpoint_id = router.endpoint().id().to_string();
272	
273	    eprintln!("[iroh-sync] desktop endpoint ready: {endpoint_id}");
274	    Ok(IrohServerHandle {
275	        runtime,
276	        router,
277	        ticket,
278	        endpoint_id,
279	    })
280	}
281	
282	/// Start (or reuse) the phone's loopback proxy for an Iroh endpoint ticket.
283	pub fn start_iroh_sync_client(
284	    app: &AppEnv,
285	    args: StartIrohClientArgs,
286	) -> Result<IrohClientStatus, String> {
287	    let ticket = args.ticket.trim();
288	    if ticket.is_empty() {
289	        return Err("The Iroh endpoint ticket is empty.".to_string());
290	    }
291	    let parsed = EndpointTicket::from_str(ticket)
292	        .map_err(|error| format!("The Iroh endpoint ticket is invalid: {error}"))?;
293	    let pairing_token = pairing_token_from_ssh_remote(&args.remote_url);
294	
295	    let mut guard = CLIENT
296	        .lock()
297	        .map_err(|_| "Iroh client state is poisoned.".to_string())?;
298	    if let Some(client) = guard.as_mut() {
299	        if client.ticket == ticket {
300	            if let Some(token) = pairing_token.as_deref() {
301	                client.runtime.block_on(pair_iroh_endpoint(
302	                    client.router.endpoint(),
303	                    client.remote_addr.clone(),
304	                    token,
305	                ))?;
306	                client.pairing_token = Some(token.to_string());
307	            }
308	            return client.status_for_remote(&args.remote_url);
309	        }
310	    }
311	    if let Some(previous) = guard.take() {
312	        previous.stop();
313	    }
314	
315	    let secret = load_or_create_secret(app, "client.key")?;
316	    let blobs_path = blob_store_path(app, "client-blobs-v103")?;
317	    let runtime = runtime("Iroh sync client")?;
318	    let (router, blobs, listener) = runtime.block_on(async {
319	        let endpoint = Endpoint::builder(presets::N0)
320	            .secret_key(secret)
321	            .bind()
322	            .await
323	            .map_err(|error| format!("Failed to bind the Iroh client endpoint: {error}"))?;
324	        let store = FsStore::load(blobs_path)
325	            .await
326	            .map_err(|error| format!("Failed to open the phone Iroh blob store: {error}"))?;
327	        let store: BlobStore = store.into();
328	        let blobs = BlobsProtocol::new(&store, None);
329	        let router = Router::builder(endpoint)
330	            .accept(iroh_blobs::ALPN, blobs)
331	            .spawn();
332	        let listener = tokio::net::TcpListener::bind(("127.0.0.1", IROH_CLIENT_PROXY_PORT))
333	            .await
334	            .map_err(|error| {
335	                format!(
336	                "Failed to start the phone sync proxy on port {IROH_CLIENT_PROXY_PORT}: {error}"
337	            )
338	            })?;
339	        Ok::<_, String>((router, store, listener))
340	    })?;
341	
342	    let endpoint_id = parsed.endpoint_addr().id.to_string();
343	    let remote_addr = parsed.endpoint_addr().clone();
344	    let proxy_remote_addr = remote_addr.clone();
345	    let accept_endpoint = router.endpoint().clone();
346	    runtime.spawn(async move {
347	        loop {
348	            let (tcp, peer) = match listener.accept().await {
349	                Ok(value) => value,
350	                Err(error) => {
351	                    eprintln!("[iroh-sync] phone proxy stopped accepting connections: {error}");
352	                    break;
353	                }
354	            };
355	            let endpoint = accept_endpoint.clone();
356	            let remote_addr = proxy_remote_addr.clone();
357	            tokio::spawn(async move {
358	                if let Err(error) = forward_tcp_to_iroh(tcp, endpoint, remote_addr).await {
359	                    eprintln!("[iroh-sync] phone tunnel for {peer} failed: {error}");
360	                }
361	            });
362	        }
363	    });
364	
365	    let client = IrohClientHandle {
366	        runtime,
367	        router,
368	        blobs,
369	        remote_addr,
370	        pairing_token,
371	        ticket: ticket.to_string(),
372	        endpoint_id,
373	        local_port: IROH_CLIENT_PROXY_PORT,
374	    };
375	    if let Some(token) = client.pairing_token.as_deref() {
376	        if let Err(error) = client.runtime.block_on(pair_iroh_endpoint(
377	            client.router.endpoint(),
378	            client.remote_addr.clone(),
379	            token,
380	        )) {
381	            client.stop();
382	            return Err(error);
383	        }
384	    }
385	    let status = client.status_for_remote(&args.remote_url)?;
386	    eprintln!(
387	        "[iroh-sync] phone proxy ready on 127.0.0.1:{} for endpoint {}",
388	        status.local_port, status.endpoint_id
389	    );
390	    *guard = Some(client);
391	    Ok(status)
392	}
393	
394	/// Offer every local audio attachment that does not yet have an exact desktop
395	/// acknowledgement. `iroh-blobs` serves and verifies the bytes; Type's own
396	/// stream carries only the destination path and receipt metadata. Audio never
397	/// enters Git; Markdown and transcripts continue through the SSH tunnel.
398	pub fn archive_mobile_audio_with_iroh(app: &AppEnv) -> Result<IrohAudioArchiveResult, String> {
399	    let root = crate::ensured_notes_root(app)?;
400	    let recordings = crate::collect_recording_notes(&root)?;
401	    let mut result = IrohAudioArchiveResult {
402	        scanned: recordings.len(),
403	        uploaded: 0,
404	        already_archived: 0,
405	    };
406	    let guard = CLIENT
407	        .lock()
408	        .map_err(|_| "Iroh client state is poisoned.".to_string())?;
409	    let client = guard
410	        .as_ref()
411	        .ok_or_else(|| "Start the Iroh sync connection before archiving audio.".to_string())?;
412	
413	    for recording in recordings {
414	        if !recording.audio_path.is_file() {
415	            continue;
416	        }
417	        let (sha256, byte_length) = crate::hash_file(&recording.audio_path)?;
418	        if crate::audio_has_desktop_ack(&root, &recording.audio_rel, &sha256, byte_length) {
419	            result.already_archived += 1;
420	            continue;
421	        }
422	        let (header, blob_tag) = client.runtime.block_on(prepare_audio_blob_offer(
423	            client.router.endpoint(),
424	            &client.blobs,
425	            &recording.audio_path,
426	            recording.audio_rel.clone(),
427	            sha256.clone(),
428	            byte_length,
429	        ))?;
430	        client.runtime.block_on(send_audio_blob_offer(
431	            client.router.endpoint(),
432	            client.remote_addr.clone(),
433	            &header,
434	        ))?;
435	        // The temporary tag keeps the source alive for the entire transfer.
436	        // Dropping it makes the imported cache entry eligible for blob-store GC.
437	        drop(blob_tag);
438	        crate::record_desktop_audio_ack(&root, recording.audio_rel, sha256, byte_length)?;
439	        result.uploaded += 1;
440	    }
441	
442	    let repo = crate::ensure_git_repo(&root)?;
443	    crate::set_audio_git_exclusion(&repo, true)?;
444	    Ok(result)
445	}
446	
447	pub fn set_mobile_audio_git_exclusion(app: &AppEnv, enabled: bool) -> Result<(), String> {
448	    let root = crate::ensured_notes_root(app)?;
449	    let repo = crate::ensure_git_repo(&root)?;
450	    crate::set_audio_git_exclusion(&repo, enabled)
451	}
452	
453	/// Stop the process-global phone proxy. Safe when no proxy is running.
454	pub fn shutdown_iroh_sync_client() {
455	    if let Ok(mut guard) = CLIENT.lock() {
456	        if let Some(client) = guard.take() {
457	            client.stop();
458	        }
459	    }
460	}
461	
462	async fn handle_iroh_connection(
463	    connection: Connection,
464	    target_port: u16,
465	    repo_root: PathBuf,
466	    endpoint: Endpoint,
467	    blobs: BlobStore,
468	    auth: IrohServerAuth,
469	) -> Result<(), String> {
470	    let remote_endpoint_id = connection.remote_id().to_string();
471	    let (send, mut recv) = connection
472	        .accept_bi()
473	        .await
474	        .map_err(|error| format!("Iroh stream failed: {error}"))?;
475	    let mut handshake = [0u8; IROH_SSH_HANDSHAKE.len()];
476	    recv.read_exact(&mut handshake)
477	        .await
478	        .map_err(|error| format!("Iroh handshake failed: {error}"))?;
479	    if &handshake == IROH_AUDIO_HANDSHAKE {
480	        return receive_audio_blob_offer(
481	            send,
482	            recv,
483	            repo_root,
484	            endpoint,
485	            blobs,
486	            remote_endpoint_id,
487	            auth,
488	        )
489	        .await;
490	    }
491	    if &handshake == IROH_PAIR_HANDSHAKE {
492	        return receive_iroh_pairing(send, recv, remote_endpoint_id, auth).await;
493	    }
494	    if &handshake != IROH_SSH_HANDSHAKE {
495	        return Err("Iroh handshake was not recognized.".to_string());
496	    }
497	    let tcp = tokio::net::TcpStream::connect(("127.0.0.1", target_port))
498	        .await
499	        .map_err(|error| format!("Could not reach the desktop SSH server: {error}"))?;
500	    forward_bidi(tcp, send, recv).await
501	}
