503	async fn pair_iroh_endpoint(
504	    endpoint: &Endpoint,
505	    remote_addr: EndpointAddr,
506	    pairing_token: &str,
507	) -> Result<(), String> {
508	    let connection = endpoint
509	        .connect(remote_addr, IROH_ALPN)
510	        .await
511	        .map_err(|error| format!("Could not reach the desktop for Iroh pairing: {error}"))?;
512	    let (mut send, mut recv) = connection
513	        .open_bi()
514	        .await
515	        .map_err(|error| format!("Could not open the Iroh pairing stream: {error}"))?;
516	    let token = pairing_token.as_bytes();
517	    let token_len = u16::try_from(token.len())
518	        .map_err(|_| "The direct-sync pairing token is invalid.".to_string())?;
519	    send.write_all(IROH_PAIR_HANDSHAKE)
520	        .await
521	        .map_err(|error| format!("Could not start Iroh pairing: {error}"))?;
522	    send.write_u16(token_len)
523	        .await
524	        .map_err(|error| format!("Could not send the Iroh pairing token: {error}"))?;
525	    send.write_all(token)
526	        .await
527	        .map_err(|error| format!("Could not send the Iroh pairing token: {error}"))?;
528	    send.finish()
529	        .map_err(|error| format!("Could not finish Iroh pairing: {error}"))?;
530	    match recv
531	        .read_u8()
532	        .await
533	        .map_err(|error| format!("The desktop did not acknowledge Iroh pairing: {error}"))?
534	    {
535	        1 => Ok(()),
536	        _ => Err("The desktop rejected Iroh pairing. Scan the current QR again.".to_string()),
537	    }
538	}
