540	async fn receive_iroh_pairing(
541	    mut send: iroh::endpoint::SendStream,
542	    mut recv: iroh::endpoint::RecvStream,
543	    remote_endpoint_id: String,
544	    auth: IrohServerAuth,
545	) -> Result<(), String> {
546	    let token_len = recv
547	        .read_u16()
548	        .await
549	        .map_err(|error| format!("Could not read the Iroh pairing token: {error}"))?
550	        as usize;
551	    if token_len == 0 || token_len > MAX_PAIRING_TOKEN_BYTES {
552	        let _ = send.write_u8(0).await;
553	        let _ = send.finish();
554	        return Err("The Iroh pairing token has an invalid size.".to_string());
555	    }
556	    let mut token = vec![0u8; token_len];
557	    recv.read_exact(&mut token)
558	        .await
559	        .map_err(|error| format!("Could not read the Iroh pairing token: {error}"))?;
560	    let token =
561	        String::from_utf8(token).map_err(|_| "The Iroh pairing token is invalid.".to_string())?;
562	    let result = auth.authorize_with_pairing_token(&remote_endpoint_id, &token);
563	    send.write_u8(u8::from(result.is_ok()))
564	        .await
565	        .map_err(|error| format!("Could not acknowledge Iroh pairing: {error}"))?;
566	    send.finish()
567	        .map_err(|error| format!("Could not finish Iroh pairing: {error}"))?;
568	    result
569	}
