571	async fn forward_tcp_to_iroh(
572	    tcp: tokio::net::TcpStream,
573	    endpoint: Endpoint,
574	    remote_addr: EndpointAddr,
575	) -> Result<(), String> {
576	    let connection = endpoint
577	        .connect(remote_addr, IROH_ALPN)
578	        .await
579	        .map_err(|error| format!("Could not reach the desktop over Iroh: {error}"))?;
580	    let (mut send, recv) = connection
581	        .open_bi()
582	        .await
583	        .map_err(|error| format!("Could not open the Iroh sync stream: {error}"))?;
584	    // QUIC opens streams lazily; writing first makes the desktop's accept_bi
585	    // resolve even if libgit2 has not sent an SSH byte yet.
586	    send.write_all(IROH_SSH_HANDSHAKE)
587	        .await
588	        .map_err(|error| format!("Could not start the Iroh sync stream: {error}"))?;
589	    forward_bidi(tcp, send, recv).await
590	}
