592	async fn prepare_audio_blob_offer(
593	    endpoint: &Endpoint,
594	    blobs: &BlobStore,
595	    audio_path: &Path,
596	    audio_rel: String,
597	    sha256: String,
598	    byte_length: u64,
599	) -> Result<(AudioUploadHeader, TempTag), String> {
600	    let absolute = std::path::absolute(audio_path)
601	        .map_err(|error| format!("Could not resolve the recording path: {error}"))?;
602	    let added = blobs
603	        .blobs()
604	        .add_path(absolute)
605	        .temp_tag()
606	        .await
607	        .map_err(|error| format!("Could not hash the recording with iroh-blobs: {error}"))?;
608	    if added.format() != BlobFormat::Raw {
609	        return Err("The recording was imported as an unexpected blob collection.".to_string());
610	    }
611	    tokio::time::timeout(IROH_ONLINE_TIMEOUT, endpoint.online())
612	        .await
613	        .map_err(|_| "The phone could not publish an Iroh blob address in time.".to_string())?;
614	    let ticket = BlobTicket::new(endpoint.addr(), added.hash(), added.format());
615	    let header = AudioUploadHeader {
616	        audio_path: audio_rel,
617	        sha256,
618	        blake3: added.hash().to_string(),
619	        byte_length,
620	        blob_ticket: ticket.to_string(),
621	    };
622	    Ok((header, added))
623	}
