625	async fn send_audio_blob_offer(
626	    endpoint: &Endpoint,
627	    remote_addr: EndpointAddr,
628	    header: &AudioUploadHeader,
629	) -> Result<(), String> {
630	    let connection = endpoint
631	        .connect(remote_addr, IROH_ALPN)
632	        .await
633	        .map_err(|error| format!("Could not reach the desktop for audio archive: {error}"))?;
634	    let (mut send, mut recv) = connection
635	        .open_bi()
636	        .await
637	        .map_err(|error| format!("Could not open the Iroh audio stream: {error}"))?;
638	    let header_json = serde_json::to_vec(header)
639	        .map_err(|error| format!("Failed to encode the audio archive request: {error}"))?;
640	    let header_len = u32::try_from(header_json.len())
641	        .map_err(|_| "The audio archive header is too large.".to_string())?;
642	    send.write_all(IROH_AUDIO_HANDSHAKE)
643	        .await
644	        .map_err(|error| format!("Could not start the Iroh audio stream: {error}"))?;
645	    send.write_u32(header_len)
646	        .await
647	        .map_err(|error| format!("Could not send the audio archive header: {error}"))?;
648	    send.write_all(&header_json)
649	        .await
650	        .map_err(|error| format!("Could not send the audio archive header: {error}"))?;
651	    send.finish()
652	        .map_err(|error| format!("Could not finish the audio blob offer: {error}"))?;
653	
654	    let response_len = recv
655	        .read_u32()
656	        .await
657	        .map_err(|error| format!("Desktop did not acknowledge the audio archive: {error}"))?
658	        as usize;
659	    if response_len > MAX_AUDIO_HEADER_BYTES {
660	        return Err("The desktop returned an invalid audio acknowledgement.".to_string());
661	    }
662	    let mut response_json = vec![0u8; response_len];
663	    recv.read_exact(&mut response_json)
664	        .await
665	        .map_err(|error| format!("Could not read the desktop audio acknowledgement: {error}"))?;
666	    let response: AudioUploadResponse = serde_json::from_slice(&response_json)
667	        .map_err(|error| format!("The desktop audio acknowledgement is invalid: {error}"))?;
668	    if !response.ok {
669	        return Err(response
670	            .error
671	            .unwrap_or_else(|| "The desktop rejected the audio archive.".to_string()));
672	    }
673	    if response.sha256.as_deref() != Some(header.sha256.as_str())
674	        || response.blake3.as_deref() != Some(header.blake3.as_str())
675	        || response.byte_length != Some(header.byte_length)
676	    {
677	        return Err("The desktop acknowledged different audio bytes.".to_string());
678	    }
679	    Ok(())
680	}
