682	async fn receive_audio_blob_offer(
683	    mut send: iroh::endpoint::SendStream,
684	    mut recv: iroh::endpoint::RecvStream,
685	    repo_root: PathBuf,
686	    endpoint: Endpoint,
687	    blobs: BlobStore,
688	    remote_endpoint_id: String,
689	    auth: IrohServerAuth,
690	) -> Result<(), String> {
691	    let result = receive_audio_blob_inner(
692	        &mut recv,
693	        &repo_root,
694	        &endpoint,
695	        &blobs,
696	        &remote_endpoint_id,
697	        &auth,
698	    )
699	    .await;
700	    let response = match &result {
701	        Ok((sha256, blake3, byte_length)) => AudioUploadResponse {
702	            ok: true,
703	            error: None,
704	            sha256: Some(sha256.clone()),
705	            blake3: Some(blake3.clone()),
706	            byte_length: Some(*byte_length),
707	        },
708	        Err(error) => AudioUploadResponse {
709	            ok: false,
710	            error: Some(error.clone()),
711	            sha256: None,
712	            blake3: None,
713	            byte_length: None,
714	        },
715	    };
716	    let response_json = serde_json::to_vec(&response)
717	        .map_err(|error| format!("Failed to encode the audio acknowledgement: {error}"))?;
718	    send.write_u32(response_json.len() as u32)
719	        .await
720	        .map_err(|error| format!("Failed to send the audio acknowledgement: {error}"))?;
721	    send.write_all(&response_json)
722	        .await
723	        .map_err(|error| format!("Failed to send the audio acknowledgement: {error}"))?;
724	    send.finish()
725	        .map_err(|error| format!("Failed to finish the audio acknowledgement: {error}"))?;
726	    result.map(|_| ())
727	}
