729	async fn receive_audio_blob_inner(
730	    recv: &mut iroh::endpoint::RecvStream,
731	    repo_root: &Path,
732	    endpoint: &Endpoint,
733	    blobs: &BlobStore,
734	    remote_endpoint_id: &str,
735	    auth: &IrohServerAuth,
736	) -> Result<(String, String, u64), String> {
737	    let header_len = recv
738	        .read_u32()
739	        .await
740	        .map_err(|error| format!("Could not read the audio archive header: {error}"))?
741	        as usize;
742	    if header_len == 0 || header_len > MAX_AUDIO_HEADER_BYTES {
743	        return Err("The audio archive header has an invalid size.".to_string());
744	    }
745	    let mut header_json = vec![0u8; header_len];
746	    recv.read_exact(&mut header_json)
747	        .await
748	        .map_err(|error| format!("Could not read the audio archive header: {error}"))?;
749	    let header: AudioUploadHeader = serde_json::from_slice(&header_json)
750	        .map_err(|error| format!("The audio archive header is invalid: {error}"))?;
751	    if !auth.is_authorized(remote_endpoint_id) {
752	        return Err("This Iroh endpoint is not paired for audio sync. Scan the QR again.".into());
753	    }
754	    if header.byte_length > MAX_AUDIO_BYTES {
755	        return Err("The audio archive exceeds the 2 GiB safety limit.".to_string());
756	    }
757	    let relative = crate::sanitize_relative(&header.audio_path)?;
758	    let target = repo_root.join(&relative);
759	    if !crate::is_recording_audio_path_allowed(repo_root, &target) {
760	        return Err("Only recording audio paths can be archived.".to_string());
761	    }
762	    let repo = git2::Repository::open(repo_root)
763	        .map_err(|error| format!("The desktop notes Git repo is unavailable: {error}"))?;
764	    crate::set_audio_git_exclusion(&repo, true)?;
765	    let ticket = BlobTicket::from_str(&header.blob_ticket)
766	        .map_err(|error| format!("The recording blob ticket is invalid: {error}"))?;
767	    if ticket.format() != BlobFormat::Raw || ticket.hash().to_string() != header.blake3 {
768	        return Err("The recording blob ticket does not match its declared hash.".to_string());
769	    }
770	    if target.exists() {
771	        let existing_path = target.clone();
772	        let (sha256, byte_length) =
773	            tokio::task::spawn_blocking(move || crate::hash_file(&existing_path))
774	                .await
775	                .map_err(|error| format!("Desktop audio verification worker failed: {error}"))??;
776	        if sha256 != header.sha256 || byte_length != header.byte_length {
777	            return Err("The desktop already has different audio at this path.".to_string());
778	        }
779	        return Ok((sha256, header.blake3, byte_length));
780	    }
781	    let parent = target
782	        .parent()
783	        .ok_or_else(|| "The audio archive path has no parent.".to_string())?;
784	    tokio::fs::create_dir_all(parent)
785	        .await
786	        .map_err(|error| format!("Could not create the desktop audio folder: {error}"))?;
787	    let file_name = target
788	        .file_name()
789	        .and_then(|name| name.to_str())
790	        .ok_or_else(|| "The audio archive filename is invalid.".to_string())?;
791	    let temporary = parent.join(format!(".{file_name}.iroh-{}.part", Uuid::now_v7()));
792	    let blob_connection = endpoint
793	        .connect(ticket.addr().clone(), iroh_blobs::ALPN)
794	        .await
795	        .map_err(|error| format!("Could not reach the phone's recording blob: {error}"))?;
796	    blobs
797	        .remote()
798	        .fetch(blob_connection, ticket.hash())
799	        .await
800	        .map_err(|error| format!("Could not download the recording blob: {error}"))?;
801	    blobs
802	        .blobs()
803	        .export(ticket.hash(), temporary.clone())
804	        .await
805	        .map_err(|error| format!("Could not export the recording blob: {error}"))?;
806	    let verify_path = temporary.clone();
807	    let verified = tokio::task::spawn_blocking(move || crate::hash_file(&verify_path)).await;
808	    let (sha256, byte_length) = match verified {
809	        Ok(Ok(value)) => value,
810	        Ok(Err(error)) => {
811	            let _ = tokio::fs::remove_file(&temporary).await;
812	            return Err(error);
813	        }
814	        Err(error) => {
815	            let _ = tokio::fs::remove_file(&temporary).await;
816	            return Err(format!("Audio verification worker failed: {error}"));
817	        }
818	    };
819	    if sha256 != header.sha256 || byte_length != header.byte_length {
820	        let _ = tokio::fs::remove_file(&temporary).await;
821	        return Err("The received audio hash does not match the phone.".to_string());
822	    }
823	    if let Err(error) = tokio::fs::rename(&temporary, &target).await {
824	        let _ = tokio::fs::remove_file(&temporary).await;
825	        return Err(format!(
826	            "Could not finalize the desktop audio archive: {error}"
827	        ));
828	    }
829	    Ok((sha256, header.blake3, byte_length))
830	}
