832	async fn forward_bidi(
833	    tcp: tokio::net::TcpStream,
834	    mut iroh_send: iroh::endpoint::SendStream,
835	    mut iroh_recv: iroh::endpoint::RecvStream,
836	) -> Result<(), String> {
837	    let (mut tcp_read, mut tcp_write) = tcp.into_split();
838	    let upload = async {
839	        tokio::io::copy(&mut tcp_read, &mut iroh_send)
840	            .await
841	            .map_err(|error| format!("Tunnel upload failed: {error}"))?;
842	        iroh_send
843	            .finish()
844	            .map_err(|error| format!("Tunnel upload close failed: {error}"))?;
845	        Ok::<(), String>(())
846	    };
847	    let download = async {
848	        tokio::io::copy(&mut iroh_recv, &mut tcp_write)
849	            .await
850	            .map_err(|error| format!("Tunnel download failed: {error}"))?;
851	        tcp_write
852	            .shutdown()
853	            .await
854	            .map_err(|error| format!("Tunnel download close failed: {error}"))?;
855	        Ok::<(), String>(())
856	    };
857	    tokio::try_join!(upload, download)?;
858	    Ok(())
859	}
