938	fn rewrite_ssh_remote_to_loopback(remote_url: &str, port: u16) -> Result<String, String> {
939	    let remote = remote_url.trim();
940	    let rest = remote
941	        .strip_prefix("ssh://")
942	        .or_else(|| remote.strip_prefix("SSH://"))
943	        .ok_or_else(|| "Iroh sync currently supports ssh:// remotes only.".to_string())?;
944	    let (authority, path) = rest
945	        .split_once('/')
946	        .ok_or_else(|| "The SSH sync remote is missing its repository path.".to_string())?;
947	    if path.is_empty() {
948	        return Err("The SSH sync remote is missing its repository path.".to_string());
949	    }
950	    let user = authority
951	        .rsplit_once('@')
952	        .map(|(user, _)| format!("{user}@"))
953	        .unwrap_or_default();
954	    Ok(format!("ssh://{user}127.0.0.1:{port}/{path}"))
955	}
