957	fn pairing_token_from_ssh_remote(remote_url: &str) -> Option<String> {
958	    let remote = remote_url.trim();
959	    let rest = remote
960	        .strip_prefix("ssh://")
961	        .or_else(|| remote.strip_prefix("SSH://"))?;
962	    let (userinfo, _) = rest.split_once('@')?;
963	    let token = userinfo.strip_prefix("pair-")?;
964	    (!token.is_empty() && token.chars().all(|char| char.is_ascii_hexdigit()))
965	        .then(|| token.to_string())
966	}
