989	            pairing_token_from_ssh_remote("ssh://pair-deadbeef@example.test/Notes").as_deref(),
990	            Some("deadbeef")
991	        );
992	        assert!(pairing_token_from_ssh_remote("ssh://example.test/Notes").is_none());
993	        assert!(pairing_token_from_ssh_remote("ssh://pair-not-hex@example.test/Notes").is_none());
994	    }
995	
996	    #[test]
997	    fn pairing_token_registers_an_iroh_endpoint_once() {
998	        let folder = std::env::temp_dir().join(format!("type-iroh-auth-{}", Uuid::now_v7()));
999	        fs::create_dir_all(&folder).unwrap();
1000	        let auth = IrohServerAuth {
1001	            pairing_token: Arc::new(Mutex::new("deadbeef".to_string())),
1002	            endpoints_path: folder.join(IROH_ENDPOINTS_FILE),
1003	            endpoints_lock: Arc::new(Mutex::new(())),
1004	        };
1005	        assert!(!auth.is_authorized("phone-endpoint"));
1006	        assert!(auth
1007	            .authorize_with_pairing_token("phone-endpoint", "bad0cafe")
1008	            .is_err());
1009	        auth.authorize_with_pairing_token("phone-endpoint", "deadbeef")
1010	            .unwrap();
1011	        assert!(auth.is_authorized("phone-endpoint"));
1012	        assert_eq!(
1013	            load_authorized_iroh_endpoints(&auth.endpoints_path),
