1	//! Local-network ("LAN" / iPhone-hotspot) SSH Git server.
2	//!
3	//! Lets a desktop machine host its notes repository over an embedded SSH server
4	//! with QR-based key pairing, so a phone on the same Wi-Fi or hotspot can
5	//! clone/pull/push without an external remote, macOS Remote Login, or
6	//! plaintext `git://`.
7	//!
8	//! Hosting requires the `git` command-line binary for `git-upload-pack` /
9	//! `git-receive-pack` and is desktop-only; on mobile the commands report
10	//! `supported = false`.
11	
12	use crate::AppEnv;
13	use serde::Serialize;
14	
15	use mdns_sd::{ServiceDaemon, ServiceEvent};
16	use std::{
17	    collections::HashMap,
18	    time::{Duration, Instant},
19	};
20	
21	use crate::ensured_notes_root;
22	use crate::ports::local_sync::LocalSyncGateway;
23	
24	#[cfg(desktop)]
25	mod devices;
26	#[cfg(desktop)]
27	mod ssh_server;
28	
29	#[cfg(desktop)]
30	use crate::{ensure_git_repo, resolve_target_branch, switch_or_prepare_branch};
31	#[cfg(desktop)]
32	use std::{
33	    fs,
