37	    sync::{Arc, Mutex},
38	};
39	
40	/// Default local-sync port. It intentionally reuses the old git-daemon port so
41	/// existing firewall prompts/rules continue to apply, but the protocol is SSH.
42	pub const LOCAL_SYNC_PORT: u16 = 9418;
43	const LOCAL_SYNC_AUTO_START_FILE: &str = "direct-sync-enabled";
44	
45	/// Bonjour/mDNS service type the desktop advertises and clients browse for.
46	const MDNS_SERVICE_TYPE: &str = "_typenotes-sync._tcp.local.";
47	
48	#[cfg(desktop)]
49	const GIT_MISSING_MSG: &str = "Hosting a local sync server needs the Git command-line tools. On macOS install them with: xcode-select --install";
50	
51	#[cfg(not(desktop))]
52	const NOT_SUPPORTED_MSG: &str = "Hosting a local sync server is only available in the desktop app.";
53	
54	#[derive(Serialize, Clone)]
55	pub struct LocalSyncServerStatus {
56	    pub supported: bool,
57	    pub git_available: bool,
58	    pub running: bool,
59	    pub host: Option<String>,
60	    pub port: u16,
61	    pub branch: Option<String>,
62	    pub ssh_url: Option<String>,
