89	// ── Running daemon state ─────────────────────────────────────────────────────
90	
91	#[cfg(desktop)]
92	struct RunningDaemon {
93	    server: ssh_server::SshServerHandle,
94	    host: Option<String>,
95	    served_name: String,
96	    branch: String,
97	    repo_path: PathBuf,
98	    /// Shared with the SSH server, which rotates it after each pairing —
99	    /// status polls read the live value so the QR always shows a valid token.
100	    pairing_token: std::sync::Arc<Mutex<String>>,
101	    devices_path: PathBuf,
102	    host_key_sha256: String,
103	    /// Optional direct/relay transport layered around the loopback SSH server.
104	    iroh: Option<crate::IrohServerHandle>,
105	    iroh_error: Option<String>,
106	    /// mDNS advertisement handle, present when discovery is active.
107	    mdns: Option<MdnsAdvert>,
108	}
109	
110	#[cfg(desktop)]
111	struct MdnsAdvert {
112	    daemon: ServiceDaemon,
113	    fullname: String,
114	}
115	
116	#[cfg(desktop)]
117	static DAEMON: Mutex<Option<RunningDaemon>> = Mutex::new(None);
118	
119	/// Called after the embedded server accepts a push from a phone. A push lands
120	/// files in the live working tree completely outside the frontend's view, so
121	/// the shell registers a listener here (a Tauri event emitter) and refreshes
122	/// the notes UI — otherwise incoming notes stay invisible until app restart.
123	#[cfg(desktop)]
124	static PUSH_LISTENER: Mutex<Option<Box<dyn Fn() + Send + Sync>>> = Mutex::new(None);
125	
126	#[cfg(desktop)]
127	pub fn set_local_sync_push_listener(listener: Box<dyn Fn() + Send + Sync>) {
128	    if let Ok(mut guard) = PUSH_LISTENER.lock() {
129	        *guard = Some(listener);
130	    }
131	}
132	
133	#[cfg(desktop)]
134	fn notify_local_sync_push_received() {
135	    if let Ok(guard) = PUSH_LISTENER.lock() {
136	        if let Some(listener) = guard.as_ref() {
137	            listener();
138	        }
139	    }
140	}
