142	/// Core local-sync gateway. Child-process and mDNS state stay in this
143	/// outer adapter rather than leaking into commands or application services.
144	pub struct LocalSyncAdapter {
145	    app: AppEnv,
146	}
147	
148	impl LocalSyncAdapter {
149	    pub fn new(app: AppEnv) -> Self {
150	        Self { app }
151	    }
152	}
153	
154	impl LocalSyncGateway for LocalSyncAdapter {
155	    type Status = LocalSyncServerStatus;
156	    type Discovered = DiscoveredServer;
157	
158	    fn status(&self) -> Result<Self::Status, String> {
159	        local_sync_server_status(&self.app)
160	    }
161	
162	    fn start(&self) -> Result<Self::Status, String> {
163	        start_local_sync_server_impl(&self.app)
164	    }
165	
166	    fn stop(&self) -> Result<Self::Status, String> {
167	        stop_local_sync_server_impl(&self.app)
168	    }
169	
170	    fn discover(&self, timeout_ms: u64) -> Result<Vec<Self::Discovered>, String> {
171	        discover_local_sync_servers_impl(timeout_ms)
172	    }
173	}
174	
175	// ── Public API (called by the command layer) ─────────────────────────────────
176	
177	pub fn local_sync_server_status(app: &AppEnv) -> Result<LocalSyncServerStatus, String> {
178	    let repo_path = ensured_notes_root(app)?.to_string_lossy().to_string();
179	
180	    #[cfg(not(desktop))]
181	    {
182	        Ok(unsupported_status(repo_path))
183	    }
184	
185	    #[cfg(desktop)]
186	    {
187	        let guard = DAEMON
188	            .lock()
189	            .map_err(|_| "local sync server state is poisoned".to_string())?;
190	        let git_available = locate_git().is_some();
191	        Ok(match guard.as_ref() {
192	            Some(daemon) => running_status(daemon),
193	            None => idle_status(git_available, repo_path),
194	        })
195	    }
196	}
197	
198	pub fn start_local_sync_server_impl(app: &AppEnv) -> Result<LocalSyncServerStatus, String> {
199	    #[cfg(not(desktop))]
200	    {
201	        let _ = app;
202	        Err(NOT_SUPPORTED_MSG.to_string())
203	    }
204	
205	    #[cfg(desktop)]
206	    {
207	        let root = ensured_notes_root(app)?;
208	        let git = locate_git().ok_or_else(|| GIT_MISSING_MSG.to_string())?;
209	        eprintln!("[local-sync] start requested: repo='{}'", root.display());
210	
211	        let mut guard = DAEMON
212	            .lock()
213	            .map_err(|_| "local sync server state is poisoned".to_string())?;
214	
215	        // Already running? Return current status (idempotent).
216	        if let Some(daemon) = guard.as_ref() {
217	            eprintln!(
218	                "[local-sync] start skipped: server already running for repo='{}' branch='{}'",
219	                daemon.repo_path.display(),
220	                daemon.branch
221	            );
222	            return Ok(running_status(daemon));
223	        }
224	
225	        // Make sure the notes folder is a repo and will accept pushes to its
226	        // checked-out branch by updating the working tree. Pending desktop
227	        // edits are committed by the server just before it serves each fetch
228	        // or push (see ssh_server), so starting — including the settings
229	        // page's auto-start — never creates commits by itself.
230	        let repo = ensure_git_repo(&root)?;
231	        repo.config()
232	            .and_then(|mut cfg| cfg.set_str("receive.denyCurrentBranch", "updateInstead"))
233	            .map_err(|e| format!("Failed to configure repo for local sync: {e}"))?;
234	        let branch = resolve_target_branch(&repo, None);
235	        switch_or_prepare_branch(&repo, &branch)?;
236	        drop(repo);
237	        // Receipts are tracked metadata. The next upload-pack request will
238	        // commit them together with any pending desktop changes before the
239	        // phone fetches, matching the server's existing serve-time behavior.
240	        if let Err(error) = crate::issue_desktop_audio_receipts(&root) {
241	            eprintln!("[attachments] could not issue startup audio receipts: {error}");
242	        }
243	
244	        let served_name = root
245	            .file_name()
246	            .and_then(|name| name.to_str())
247	            .ok_or_else(|| "Notes folder name is not valid UTF-8.".to_string())?
248	            .to_string();
249	
250	        let (host_key, host_key_sha256) = devices::ensure_host_key(app)?;
251	        let (token_path, token) = devices::load_or_create_pairing_token(app)?;
252	        let pairing_token = Arc::new(Mutex::new(token));
253	        let consumed_pairing_tokens = Arc::new(Mutex::new(Vec::new()));
254	        let devices_path = devices::devices_path(app)?;
255	        let shared = Arc::new(ssh_server::ServerShared {
256	            git_path: git,
257	            repo_path: root.clone(),
258	            served_name: served_name.clone(),
259	            branch: branch.clone(),
260	            pairing_token: pairing_token.clone(),
261	            consumed_pairing_tokens,
262	            pairing_token_path: token_path,
263	            devices_path: devices_path.clone(),
264	        });
265	        let server = ssh_server::start_ssh_server(shared, &host_key, LOCAL_SYNC_PORT)?;
266	
267	        let (iroh, iroh_error) = match crate::start_iroh_sync_server(
268	            app,
269	            LOCAL_SYNC_PORT,
270	            root.clone(),
271	            pairing_token.clone(),
272	        ) {
273	            Ok(iroh) => {
274	                if let Ok(repo) = git2::Repository::open(&root) {
275	                    if let Err(error) = crate::set_audio_git_exclusion(&repo, true) {
276	                        eprintln!("[attachments] could not exclude Iroh audio from Git: {error}");
277	                    }
278	                }
279	                (Some(iroh), None)
280	            }
281	            Err(error) => {
282	                eprintln!(
283	                    "[iroh-sync] desktop endpoint unavailable; LAN sync remains active: {error}"
284	                );
285	                (None, Some(error))
286	            }
287	        };
288	
289	        // Advertise over mDNS so phones can auto-discover this server without
290	        // typing or scanning anything. Best-effort: failure never blocks hosting.
291	        // The advertised URL deliberately omits the pairing token: mDNS is
292	        // plaintext broadcast, and the token must stay QR-only (already-paired
293	        // devices authenticate by key under any username).
294	        let host = detect_lan_ip();
295	        let mdns = host.as_ref().and_then(|ip| {
296	            let ssh_url = ssh_public_url(ip, &served_name);
297	            advertise_mdns(ip, &served_name, &branch, &ssh_url)
298	        });
299	
300	        let daemon = RunningDaemon {
301	            server,
302	            host,
303	            served_name,
304	            branch,
305	            repo_path: root,
306	            pairing_token,
307	            devices_path,
308	            host_key_sha256,
309	            iroh,
310	            iroh_error,
311	            mdns,
312	        };
313	        let status = running_status(&daemon);
314	        eprintln!(
315	            "[local-sync] server running: listen=0.0.0.0:{LOCAL_SYNC_PORT} advertised_host={} branch='{}' repo='{}' paired_devices={}",
316	            daemon.host.as_deref().unwrap_or("<unknown>"),
317	            daemon.branch,
318	            daemon.repo_path.display(),
319	            status.paired_devices.len()
320	        );
321	        if let Err(error) = set_local_sync_auto_start(app, true) {
322	            eprintln!("[local-sync] could not persist auto-start preference: {error}");
323	        }
324	        *guard = Some(daemon);
325	        Ok(status)
326	    }
327	}
328	
329	pub fn stop_local_sync_server_impl(app: &AppEnv) -> Result<LocalSyncServerStatus, String> {
330	    #[cfg(not(desktop))]
331	    {
332	        let _ = app;
333	        Err(NOT_SUPPORTED_MSG.to_string())
334	    }
335	
336	    #[cfg(desktop)]
337	    {
338	        if let Err(error) = set_local_sync_auto_start(app, false) {
339	            eprintln!("[local-sync] could not clear auto-start preference: {error}");
340	        }
341	        if let Ok(mut guard) = DAEMON.lock() {
342	            if let Some(daemon) = guard.take() {
343	                eprintln!(
344	                    "[local-sync] stop requested: repo='{}' branch='{}'",
345	                    daemon.repo_path.display(),
346	                    daemon.branch
347	                );
348	                teardown_daemon(daemon);
349	            }
350	        }
351	        local_sync_server_status(app)
352	    }
353	}
354	
355	/// Whether the user has started direct sync before without explicitly
356	/// stopping it. Used by the desktop shell to restore hosting on app launch.
357	#[cfg(desktop)]
358	pub fn local_sync_auto_start_enabled(app: &AppEnv) -> bool {
359	    crate::app_data_dir(app)
360	        .map(|dir| dir.join(LOCAL_SYNC_AUTO_START_FILE).is_file())
361	        .unwrap_or(false)
362	}
363	
364	#[cfg(desktop)]
365	fn set_local_sync_auto_start(app: &AppEnv, enabled: bool) -> Result<(), String> {
366	    let path = crate::app_data_dir(app)?.join(LOCAL_SYNC_AUTO_START_FILE);
367	    if enabled {
368	        fs::write(path, b"enabled\n").map_err(|error| error.to_string())
369	    } else if path.exists() {
370	        fs::remove_file(path).map_err(|error| error.to_string())
371	    } else {
372	        Ok(())
373	    }
374	}
375	
376	/// Kill the daemon on app exit. Safe to call when nothing is running.
377	#[cfg(desktop)]
378	pub fn shutdown_local_sync_server() {
379	    if let Ok(mut guard) = DAEMON.lock() {
380	        if let Some(daemon) = guard.take() {
381	            teardown_daemon(daemon);
382	        }
383	    }
384	}
385	
386	/// Stop the mDNS advertisement (if any) and shut down the embedded SSH server.
387	#[cfg(desktop)]
388	fn teardown_daemon(mut daemon: RunningDaemon) {
389	    if let Some(advert) = daemon.mdns.take() {
390	        let _ = advert.daemon.unregister(&advert.fullname);
391	        let _ = advert.daemon.shutdown();
392	    }
393	    if let Some(iroh) = daemon.iroh.take() {
394	        iroh.stop();
395	    }
396	    daemon.server.stop();
397	}
398	
399	// ── Status builders ──────────────────────────────────────────────────────────
400	
401	#[cfg(not(desktop))]
402	fn unsupported_status(repo_path: String) -> LocalSyncServerStatus {
403	    LocalSyncServerStatus {
404	        supported: false,
405	        git_available: false,
406	        running: false,
407	        host: None,
408	        port: LOCAL_SYNC_PORT,
409	        branch: None,
410	        ssh_url: None,
411	        host_key_sha256: None,
412	        iroh_ticket: None,
413	        iroh_endpoint_id: None,
414	        paired_devices: Vec::new(),
415	        repo_path,
416	        error: None,
417	    }
418	}
419	
420	#[cfg(desktop)]
421	fn idle_status(git_available: bool, repo_path: String) -> LocalSyncServerStatus {
422	    LocalSyncServerStatus {
423	        supported: true,
424	        git_available,
425	        running: false,
426	        host: None,
427	        port: LOCAL_SYNC_PORT,
428	        branch: None,
429	        ssh_url: None,
430	        host_key_sha256: None,
431	        iroh_ticket: None,
432	        iroh_endpoint_id: None,
433	        paired_devices: Vec::new(),
434	        repo_path,
435	        error: None,
436	    }
437	}
438	
439	#[cfg(desktop)]
440	fn running_status(daemon: &RunningDaemon) -> LocalSyncServerStatus {
441	    let token = daemon
442	        .pairing_token
443	        .lock()
444	        .map(|t| t.clone())
445	        .unwrap_or_default();
446	    let ssh_url = daemon
447	        .host
448	        .as_deref()
449	        .map(|host| ssh_pairing_url(host, &daemon.served_name, &token))
450	        .or_else(|| {
451	            daemon
452	                .iroh
453	                .as_ref()
454	                .map(|_| ssh_pairing_url("iroh.invalid", &daemon.served_name, &token))
455	        });
456	    let paired_devices = devices::list_devices(&daemon.devices_path)
457	        .into_iter()
458	        .map(|device| PairedDeviceInfo {
459	            name: device.name,
460	            added_ms: device.added_ms,
461	        })
462	        .collect();
463	    LocalSyncServerStatus {
464	        supported: true,
465	        git_available: true,
466	        running: true,
467	        host: daemon.host.clone(),
468	        port: LOCAL_SYNC_PORT,
469	        branch: Some(daemon.branch.clone()),
470	        ssh_url,
471	        host_key_sha256: Some(daemon.host_key_sha256.clone()),
472	        iroh_ticket: daemon.iroh.as_ref().map(|iroh| iroh.ticket().to_string()),
473	        iroh_endpoint_id: daemon
474	            .iroh
475	            .as_ref()
476	            .map(|iroh| iroh.endpoint_id().to_string()),
477	        paired_devices,
478	        repo_path: daemon.repo_path.to_string_lossy().to_string(),
479	        error: daemon.iroh_error.clone(),
480	    }
481	}
482	
483	// ── Helpers ──────────────────────────────────────────────────────────────────
484	
485	/// Locate a usable `git` binary: PATH first, then common GUI-app install spots
486	/// (Finder/Dock-launched apps get a minimal PATH, mirroring whisper_env).
487	#[cfg(desktop)]
488	fn locate_git() -> Option<PathBuf> {
489	    let candidates = [
490	        "git",
491	        "/usr/bin/git",
492	        "/opt/homebrew/bin/git",
493	        "/usr/local/bin/git",
494	    ];
495	    candidates.into_iter().map(PathBuf::from).find(|candidate| {
496	        Command::new(candidate)
497	            .arg("--version")
498	            .output()
499	            .map(|out| out.status.success())
500	            .unwrap_or(false)
501	    })
502	}
503	
504	/// Best-effort detection of the outbound LAN/hotspot IPv4. Uses the classic
505	/// "connected UDP socket" trick: connecting does a route lookup and reveals the
506	/// source address for that route without sending any packets. We probe a few
507	/// targets so it works on shared Wi-Fi, on iPhone hotspot (gateway 172.20.10.1),
508	/// and on networks without internet access.
509	#[cfg(desktop)]
510	fn detect_lan_ip() -> Option<String> {
511	    const TARGETS: [&str; 5] = [
512	        "8.8.8.8:80",
513	        "1.1.1.1:80",
514	        "172.20.10.1:80", // iPhone personal-hotspot gateway
515	        "192.168.1.1:80",
516	        "192.168.0.1:80",
517	    ];
518	    for target in TARGETS {
519	        let Ok(socket) = UdpSocket::bind("0.0.0.0:0") else {
520	            continue;
521	        };
522	        if socket.connect(target).is_err() {
523	            continue;
524	        }
525	        if let Ok(addr) = socket.local_addr() {
526	            if let IpAddr::V4(v4) = addr.ip() {
527	                if !v4.is_loopback() && !v4.is_unspecified() {
528	                    return Some(v4.to_string());
529	                }
530	            }
531	        }
532	    }
533	    None
534	}
535	
536	#[cfg(desktop)]
537	fn current_user() -> String {
538	    std::env::var("USER")
539	        .or_else(|_| std::env::var("USERNAME"))
540	        .unwrap_or_else(|_| "user".to_string())
541	}
542	
543	#[cfg(desktop)]
544	fn ssh_pairing_url(host: &str, served_name: &str, pairing_token: &str) -> String {
545	    format!(
546	        "ssh://pair-{pairing_token}@{host}:{LOCAL_SYNC_PORT}/{}",
547	        encode_url_path_segment(served_name)
548	    )
549	}
550	
551	/// Token-less variant, safe for plaintext broadcast (mDNS). Only devices whose
552	/// keys are already paired can use it.
553	#[cfg(desktop)]
554	fn ssh_public_url(host: &str, served_name: &str) -> String {
555	    format!(
556	        "ssh://{host}:{LOCAL_SYNC_PORT}/{}",
557	        encode_url_path_segment(served_name)
558	    )
559	}
560	
561	#[cfg(desktop)]
562	fn encode_url_path_segment(value: &str) -> String {
563	    let mut output = String::new();
564	    for byte in value.bytes() {
565	        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
566	            output.push(byte as char);
567	        } else {
568	            output.push_str(&format!("%{byte:02X}"));
569	        }
570	    }
571	    output
572	}
573	
574	/// Human-friendly label for this computer, shown on the phone's discovery list.
575	#[cfg(desktop)]
576	fn computer_label() -> String {
577	    // macOS: the user-set "Computer Name" is the friendliest.
578	    if let Ok(out) = Command::new("scutil")
579	        .arg("--get")
580	        .arg("ComputerName")
581	        .output()
582	    {
583	        if out.status.success() {
584	            let name = String::from_utf8_lossy(&out.stdout).trim().to_string();
585	            if !name.is_empty() {
586	                return name;
587	            }
588	        }
589	    }
590	    if let Ok(out) = Command::new("hostname").output() {
591	        if out.status.success() {
592	            let name = String::from_utf8_lossy(&out.stdout)
593	                .trim()
594	                .trim_end_matches(".local")
595	                .to_string();
596	            if !name.is_empty() {
597	                return name;
598	            }
599	        }
600	    }
601	    format!("{}'s computer", current_user())
602	}
603	
604	/// DNS-label-safe version of a free-text name (for the mDNS host name).
605	#[cfg(desktop)]
606	fn sanitize_host_label(value: &str) -> String {
607	    let cleaned: String = value
608	        .chars()
609	        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
610	        .collect();
611	    let trimmed = cleaned.trim_matches('-').to_string();
612	    if trimmed.is_empty() {
613	        "type-sync".to_string()
614	    } else {
615	        trimmed
616	    }
617	}
618	
619	/// Register an mDNS service for the running server. Returns a handle to keep the
620	/// advertisement alive; dropping/unregistering it removes the service.
621	#[cfg(desktop)]
622	fn advertise_mdns(
623	    host: &str,
624	    served_name: &str,
625	    branch: &str,
626	    remote_url: &str,
627	) -> Option<MdnsAdvert> {
628	    use mdns_sd::ServiceInfo;
629	
630	    let daemon = ServiceDaemon::new().ok()?;
631	    let label = computer_label();
632	    // host_name owns the A record we publish for `host`; it just has to be unique.
633	    let host_name = format!("{}.local.", sanitize_host_label(&label));
634	    let properties = [
635	        ("url", remote_url),
636	        ("branch", branch),
637	        ("path", served_name),
638	        ("name", label.as_str()),
639	        ("transport", "ssh"),
640	    ];
641	    let info = ServiceInfo::new(
642	        MDNS_SERVICE_TYPE,
643	        &label,
644	        &host_name,
645	        host,
646	        LOCAL_SYNC_PORT,
647	        &properties[..],
648	    )
649	    .ok()?;
650	    let fullname = info.get_fullname().to_string();
651	    daemon.register(info).ok()?;
652	    Some(MdnsAdvert { daemon, fullname })
653	}
654	
655	// ── Discovery (all platforms) ────────────────────────────────────────────────
656	
657	/// Browse the local network for advertised sync servers for up to `timeout_ms`.
658	pub fn discover_local_sync_servers_impl(timeout_ms: u64) -> Result<Vec<DiscoveredServer>, String> {
659	    let timeout_ms = timeout_ms.clamp(500, 10_000);
660	    let mdns = ServiceDaemon::new().map_err(|e| format!("mDNS init failed: {e}"))?;
661	    let receiver = mdns
662	        .browse(MDNS_SERVICE_TYPE)
663	        .map_err(|e| format!("mDNS browse failed: {e}"))?;
664	
665	    let deadline = Instant::now() + Duration::from_millis(timeout_ms);
666	    let mut found: HashMap<String, DiscoveredServer> = HashMap::new();
667	    loop {
668	        let remaining = deadline.saturating_duration_since(Instant::now());
669	        if remaining.is_zero() {
670	            break;
671	        }
672	        match receiver.recv_timeout(remaining) {
673	            Ok(ServiceEvent::ServiceResolved(info)) => {
674	                if let Some(server) = discovered_from_info(&info) {
675	                    found.insert(info.fullname.clone(), server);
676	                }
677	            }
678	            Ok(_) => {}
679	            Err(_) => break,
680	        }
681	    }
682	    let _ = mdns.shutdown();
683	
684	    let mut servers: Vec<DiscoveredServer> = found.into_values().collect();
685	    servers.sort_by(|a, b| a.name.cmp(&b.name));
686	    Ok(servers)
687	}
688	
689	fn discovered_from_info(info: &mdns_sd::ResolvedService) -> Option<DiscoveredServer> {
690	    let host = info
691	        .get_addresses_v4()
692	        .into_iter()
693	        .next()
694	        .map(|v4| v4.to_string())?;
695	    let path = info.get_property_val_str("path").unwrap_or("notes");
696	    let url = info
697	        .get_property_val_str("url")
698	        .map(|value| value.to_string())
699	        .unwrap_or_else(|| format!("ssh://{host}:{}/{path}", info.port));
700	    let branch = info
701	        .get_property_val_str("branch")
702	        .unwrap_or("main")
703	        .to_string();
704	    let name = info
705	        .get_property_val_str("name")
706	        .map(|value| value.to_string())
707	        .unwrap_or_else(|| info.fullname.clone());
708	    Some(DiscoveredServer {
709	        name,
710	        host,
711	        port: info.port,
712	        url,
713	        branch,
714	    })
715	}
716

