1	import { create } from "zustand";
2	
3	import * as core from "@typenotes/mobile-core/core-api";
4	import { getErrorMessage } from "@typenotes/shared/errors";
5	import { getSyncHint } from "@typenotes/shared/format";
6	import {
7	  stripPairingUsernameFromSshRemote,
8	  type SyncDeepLinkParams,
9	} from "@typenotes/shared/sync-link";
10	import type {
11	  ConnectGitArgs,
12	  GitCommitHistoryEntry,
13	  GitSyncStatus,
14	  GitTransferProgress,
15	} from "@typenotes/shared/types";
16	
17	import {
18	  autoSyncRetryDelayMs,
19	  saveReasonHasLocalChanges,
20	  type AutoSyncState,
21	} from "../lib/sync-experience";
22	import { useNotesStore } from "./notes-store";
23	import { activeProfile, useSettingsStore } from "./settings-store";
24	
25	type SyncAction = "idle" | "refresh" | "connect" | "pull" | "push";
26	type SavedGitConnection = ConnectGitArgs & { irohTicket: string | null };
27	const AUTO_SYNC_DELAY_MS = 1_500;
28	const AUTO_SYNC_BUSY_RETRY_MS = 2_000;
29	let autoSyncTimer: ReturnType<typeof setTimeout> | null = null;
30	let autoSyncFailureCount = 0;
31	
32	const sshHostFromRemote = (remote: string): string => {
33	  const match = remote.match(/^ssh:\/\/(?:[^@/]+@)?(\[[^\]]+\]|[^/:]+)(?::\d+)?(?:\/|$)/i);
34	  return match?.[1]?.replace(/^\[|\]$/g, "") ?? "";
35	};
36	
37	const redactRemoteForLog = (remote: string | null | undefined): string => {
38	  if (!remote) {
39	    return "<none>";
40	  }
41	  const match = remote.match(/^([a-z][a-z0-9+.-]*:\/\/)([^@/?#]+)@(.+)$/i);
42	  if (!match) {
43	    return remote;
44	  }
45	  const [, scheme, userinfo, rest] = match;
46	  if (scheme.toLowerCase() === "ssh://" && userinfo.toLowerCase().startsWith("pair-")) {
47	    const token = userinfo.slice("pair-".length);
48	    return `${scheme}pair-<token:${token.slice(-6)}>@${rest}`;
49	  }
50	  return `${scheme}${userinfo.includes(":") ? "<credentials>" : userinfo}@${rest}`;
51	};
52	
53	const statusForLog = (status: GitSyncStatus | null): string =>
54	  status
55	    ? `repo=${status.repo_initialized} branch=${status.current_branch ?? "<none>"} remote=${redactRemoteForLog(
56	        status.remote_url
57	      )} ahead=${status.ahead} behind=${status.behind} dirty=${status.has_uncommitted_changes} push=${status.push_required}`
58	    : "status=<none>";
59	
60	const logSync = (message: string) => console.log(`[sync] ${message}`);
61	
62	type SyncState = {
63	  status: GitSyncStatus | null;
64	  history: GitCommitHistoryEntry[];
65	  action: SyncAction;
66	  /** Live transfer progress of the running pull/push, null when idle. */
67	  progress: GitTransferProgress | null;
68	  error: string | null;
69	  hint: string | null;
70	  autoSyncState: AutoSyncState | null;
71	  lastAutoSyncedAt: number | null;
72	  /** A scanned/deep-linked type2://sync remote waiting to be applied. */
73	  pendingLink: SyncDeepLinkParams | null;
74	  setPendingLink: (link: SyncDeepLinkParams | null) => void;
75	  refresh: () => Promise<void>;
76	  connect: (args: ConnectGitArgs) => Promise<void>;
77	  /** Persist a scanned sync link to the working folder's settings + connect. */
78	  connectFromLink: (link: SyncDeepLinkParams) => Promise<void>;
79	  pull: () => Promise<void>;
80	  push: (message?: string) => Promise<void>;
81	  /** The one-button flow: pull, then push. */
82	  syncNow: () => Promise<void>;
83	  /** Debounced, best-effort sync used after saves and foregrounding. */
84	  scheduleAutoSync: (reason: string, delayMs?: number) => void;
85	};
86	
87	export const useSyncStore = create<SyncState>((set, get) => {
88	  const savedGitConnection = (): SavedGitConnection | null => {
89	    const profile = activeProfile(useSettingsStore.getState().snapshot);
90	    const settings = profile?.settings;
91	    const remoteUrl = settings?.git_remote_url.trim();
92	    if (!settings || !remoteUrl) {
93	      return null;
94	    }
95	
96	    return {
97	      remote_url: remoteUrl,
98	      branch: settings.git_branch.trim() || null,
99	      username: settings.git_username.trim() || null,
100	      password: settings.git_password || null,
101	      irohTicket: settings.git_iroh_ticket.trim() || null,
102	    };
103	  };
104	
105	  const prepareIrohConnection = async (
106	    connection: SavedGitConnection | null
107	  ): Promise<ConnectGitArgs | null> => {
108	    if (!connection?.remote_url || !connection.irohTicket) {
109	      return connection;
110	    }
111	    logSync("iroh: ensuring phone loopback proxy is running");
112	    const proxy = await core.startIrohSyncClient({
113	      ticket: connection.irohTicket,
114	      remote_url: connection.remote_url,
115	    });
116	    logSync(`iroh: proxy ready port=${proxy.local_port} endpoint=${proxy.endpoint_id}`);
117	    return { ...connection, remote_url: proxy.local_remote_url };
118	  };
119	
120	  const prepareAudioForPush = async (connection: SavedGitConnection | null) => {
121	    if (!connection?.irohTicket) {
122	      await core.setMobileAudioGitExclusion(false);
123	      return;
124	    }
125	    const archive = await core.archiveMobileAudioWithIroh();
126	    if (archive.uploaded > 0) {
127	      logSync(`audio archive: copied ${archive.uploaded} recording(s) to desktop over Iroh`);
128	    }
129	    const prune = await core.pruneMobileAudioCache();
130	    if (prune.evicted > 0) {
131	      logSync(`audio cache: evicted ${prune.evicted} verified week-old recording(s)`);
132	    }
133	  };
134	
135	  const ensureSavedRemote = async (
136	    currentStatus: GitSyncStatus | null,
137	    connection: ConnectGitArgs | null = savedGitConnection()
138	  ): Promise<GitSyncStatus | null> => {
139	    if (!connection?.remote_url) {
140	      logSync(`saved remote: none; ${statusForLog(currentStatus)}`);
141	      return currentStatus;
142	    }
143	
144	    const expectedBranch = connection.branch ?? "main";
145	    const remoteChanged = currentStatus?.remote_url !== connection.remote_url;
146	    const durableSavedRemote = stripPairingUsernameFromSshRemote(connection.remote_url);
147	    const savedRemoteIsPairing = durableSavedRemote !== connection.remote_url;
148	    if (savedRemoteIsPairing && currentStatus?.remote_url === durableSavedRemote) {
149	      logSync(
150	        `saved remote: ignoring stale pairing URL because repo origin is durable remote=${redactRemoteForLog(
151	          currentStatus.remote_url
152	        )}`
153	      );
154	      return currentStatus;
155	    }
156	    const branchChanged =
157	      currentStatus?.current_branch != null &&
158	      currentStatus.current_branch !== expectedBranch;
159	    const needsConnect =
160	      !currentStatus?.repo_initialized || remoteChanged || branchChanged;
161	
162	    if (!needsConnect) {
163	      logSync(`saved remote: already applied; ${statusForLog(currentStatus)}`);
164	      return currentStatus;
165	    }
166	
167	    logSync(
168	      `saved remote: applying origin remote=${redactRemoteForLog(
169	        connection.remote_url
170	      )} branch=${expectedBranch} reason repo=${!currentStatus?.repo_initialized} remoteChanged=${remoteChanged} branchChanged=${branchChanged}`
171	    );
172	    return core.connectGitRepo(connection);
173	  };
174	
175	  const run = async (
176	    action: SyncAction,
177	    work: () => Promise<GitSyncStatus | null>
178	  ) => {
179	    const startedAt = Date.now();
180	    logSync(`${action}: started`);
181	    set({ action, error: null, hint: null });
182	    // Surface libgit2's transfer progress (objects/bytes) while the network
183	    // action runs; the core publishes a snapshot that is cheap to poll.
184	    const progressTimer =
185	      action === "refresh"
186	        ? null
