1	// Git sync for the active working folder — fully compatible with the desktop
2	// app: same libgit2 core, same .type/settings.json, same conflict rule
3	// (conflicts keep local and write the remote as a .conflict.md sibling).
4	//
5	// The primary flow is QR-based: the desktop's "Local network server" card
6	// shows a type2://sync QR; scanning it here (in-app camera, or the system
7	// camera via the deep link) saves the remote and connects, so syncing is one
8	// button afterwards.
9	
10	import { CameraView, useCameraPermissions } from "expo-camera";
11	import { useEffect, useRef, useState } from "react";
12	import {
13	  Modal,
14	  Pressable,
15	  RefreshControl,
16	  ScrollView,
17	  StyleSheet,
18	  Text,
19	  View,
20	} from "react-native";
21	import { useSafeAreaInsets } from "react-native-safe-area-context";
22	
23	import * as core from "@typenotes/mobile-core/core-api";
24	import { getErrorMessage } from "@typenotes/shared/errors";
25	import {
26	  formatCommitSummaryForApp,
27	  formatGitCommitStateLabel,
28	  formatGitCommitTime,
29	  formatTransferProgress,
30	  transferProgressFraction,
31	} from "@typenotes/shared/format";
32	import { parseSyncDeepLink, type SyncDeepLinkParams } from "@typenotes/shared/sync-link";
33	
34	import { useClearInstantParam } from "../navigation";
35	import { autoSyncLabel } from "../lib/sync-experience";
36	import { activeProfile, useSettingsStore } from "../state/settings-store";
37	import { useSyncStore } from "../state/sync-store";
38	import { useTheme } from "../theme";
39	import { Button, Field, InlineNote, Section } from "../ui/controls";
40	
41	const SETUP_STEPS = [
42	  "Open the Type app on your computer.",
43	  "Open desktop Settings → Sync (phone and computer on the same Wi-Fi or hotspot).",
44	  "Tap “Scan QR code” below and point the camera at the code on the computer's screen.",
45	  "After pairing, just open Type on your phone near the computer — sync starts automatically.",
46	];
47	
48	export const SyncScreen = () => {
49	  const theme = useTheme();
50	  const insets = useSafeAreaInsets();
51	  // Capture may have pushed this screen without a native animation because
52	  // its live preview already played the transition. Restore normal pop/back
53	  // behavior once this real screen is attached.
54	  useClearInstantParam();
55	  const sync = useSyncStore();
56	  const settingsStore = useSettingsStore();
57	  const profile = activeProfile(settingsStore.snapshot);
58	
59	  const [remoteUrl, setRemoteUrl] = useState(profile?.settings.git_remote_url ?? "");
60	  const [branch, setBranch] = useState(profile?.settings.git_branch ?? "main");
61	  const [username, setUsername] = useState(profile?.settings.git_username ?? "");
62	  const [password, setPassword] = useState(profile?.settings.git_password ?? "");
63	  const [sshKey, setSshKey] = useState<string | null>(null);
64	  const [showManual, setShowManual] = useState(false);
65	  const [connectedVia, setConnectedVia] = useState<string | null>(null);
66	
67	  // QR scanner state
68	  const [scannerOpen, setScannerOpen] = useState(false);
69	  const [scanNotice, setScanNotice] = useState<string | null>(null);
70	  const [permission, requestPermission] = useCameraPermissions();
71	  const handledScanRef = useRef(false);
72	
73	  useEffect(() => {
74	    void sync.refresh().catch(() => {});
75	    void core.getSshPublicKey().then(setSshKey).catch(() => {});
76	    // eslint-disable-next-line react-hooks/exhaustive-deps
77	  }, []);
78	
79	  const applyLink = async (link: SyncDeepLinkParams) => {
80	    console.log("[sync:qr] applying parsed sync link");
81	    setRemoteUrl(link.remote);
82	    setBranch(link.branch ?? "main");
83	    try {
84	      await sync.connectFromLink(link);
85	      console.log("[sync:qr] sync link applied successfully");
86	      setConnectedVia(link.name ?? link.remote);
87	    } catch (error) {
88	      console.log(`[sync:qr] failed to apply sync link: ${getErrorMessage(error)}`);
89	      // surfaced via store error state
90	    } finally {
91	      void core.getSshPublicKey().then(setSshKey).catch(() => {});
92	    }
93	  };
94	
95	  // A type2://sync deep link (system camera) lands here via the sync store.
96	  const pendingLink = useSyncStore((s) => s.pendingLink);
97	  useEffect(() => {
98	    if (pendingLink) {
99	      console.log("[sync:qr] pending deep link received");
100	      sync.setPendingLink(null);
101	      void applyLink(pendingLink);
102	    }
103	    // eslint-disable-next-line react-hooks/exhaustive-deps
104	  }, [pendingLink]);
105	
106	  const openScanner = async () => {
107	    setScanNotice(null);
108	    if (!permission?.granted) {
109	      console.log("[sync:qr] requesting camera permission");
110	      const result = await requestPermission();
111	      if (!result.granted) {
112	        console.log("[sync:qr] camera permission denied");
113	        useSyncStore.setState({
114	          error: "Camera permission is needed to scan the QR code. Enable it in system settings.",
115	        });
116	        return;
117	      }
118	    }
119	    handledScanRef.current = false;
120	    console.log("[sync:qr] scanner opened");
121	    setScannerOpen(true);
122	  };
123	
124	  const onScanned = (data: string) => {
125	    if (handledScanRef.current) {
126	      return;
127	    }
128	    const link = parseSyncDeepLink(data);
129	    if (!link) {
130	      console.log("[sync:qr] scanned QR was not a Type sync link");
131	      setScanNotice("That QR code is not a Type sync code — look for the one in desktop Settings → Sync.");
132	      return;
133	    }
134	    console.log("[sync:qr] valid Type sync QR scanned");
135	    handledScanRef.current = true;
136	    setScannerOpen(false);
137	    void applyLink(link);
138	  };
139	
140	  const busy = sync.action !== "idle";
141	  const primarySyncTitle =
142	    sync.action === "connect"
143	      ? "Connecting..."
144	      : sync.action === "pull"
145	        ? "Pulling..."
146	        : sync.action === "push"
147	          ? "Pushing..."
148	          : busy
149	            ? "Syncing..."
150	            : "Sync now";
151	  const status = sync.status;
152	  const transferLabel = formatTransferProgress(sync.progress);
153	  const transferFraction = transferProgressFraction(sync.progress);
154	  const automaticStatus = autoSyncLabel(sync.autoSyncState);
155	  // A saved remote counts as connected even when the repo's origin is missing
156	  // (e.g. an earlier connect attempt failed halfway): pull/push re-apply the
157	  // saved connection via ensureSavedRemote, so the buttons must stay usable —
158	  // otherwise a half-connected state locks the user out of the recovery path.
159	  const savedRemote = profile?.settings.git_remote_url.trim();
160	  const connected = Boolean(status?.repo_initialized && (status?.remote_url || savedRemote));
161	
162	  const connectManually = async () => {
163	    try {
164	      await settingsStore.saveGitSettings({
165	        remoteUrl,
166	        branch,
167	        username,
168	        password,
169	        commitMessage: profile?.settings.git_commit_message ?? "Sync notes",
170	        trustedSshHost: null,
171	        trustedSshHostKeySha256: null,
172	        irohTicket: null,
173	      });
174	      await sync.connect({
175	        remote_url: remoteUrl,
176	        branch,
177	        username: username || null,
178	        password: password || null,
179	      });
180	    } catch {
181	      // surfaced via store error state
182	    }
183	  };
184	
185	  return (
186	    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
187	      <ScrollView
188	        style={styles.scroll}
189	        contentContainerStyle={[
190	          styles.content,
191	          { paddingBottom: insets.bottom + 48 },
192	        ]}
193	        refreshControl={
194	          <RefreshControl
195	            refreshing={sync.action === "refresh"}
196	            onRefresh={() => void sync.refresh().catch(() => {})}
197	          />
198	        }
199	      >
200	      {!connected ? (
201	        <Section title="Sync with your computer">
202	          {SETUP_STEPS.map((step, index) => (
203	            <View key={step} style={styles.stepRow}>
204	              <Text style={[styles.stepNumber, { color: theme.colors.accent }]}>
205	                {index + 1}
206	              </Text>
207	              <Text style={[styles.stepText, { color: theme.colors.text }]}>{step}</Text>
208	            </View>
209	          ))}
210	          <Button title="Scan QR code" onPress={() => void openScanner()} disabled={busy} />
211	          <InlineNote>
212	            You can also point the system Camera app at the QR — it opens Type
213	            and sets everything up the same way.
214	          </InlineNote>
215	        </Section>
216	      ) : null}
217	
218	      <Section title={connected ? "Sync" : "Status"}>
219	        {connectedVia ? (
