    id: u64,
    /// Opaque address data for this transport.
    data: CustomAddrBytes,
}

impl fmt::Display for CustomAddr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:x}_{}", self.id, HEXLOWER.encode(self.data.as_bytes()))
