#[test]
fn a_pairing_link_whose_endpoint_id_contradicts_its_ticket_is_refused() {
    let ticket = EndpointTicket::new(EndpointAddr::new(
        SecretKey::from_bytes(&[7u8; 32]).public(),
    ))
    .to_string();
    let other = SecretKey::from_bytes(&[9u8; 32]).public().to_string();
    let error = remote_target_from_args(&StartIrohClientArgs {
        ticket: ticket.clone(),
        remote_url: "ssh://pair-deadbeef@192.168.1.2:9418/Notes".to_string(),
        endpoint_id: Some(other),
    })
    .unwrap_err();
    assert!(error.contains("does not match its ticket"), "{error}");

    // The same link without the newer field still works: the id is read
    // back out of the ticket.
    let target = remote_target_from_args(&StartIrohClientArgs {
        ticket,
        remote_url: "ssh://pair-deadbeef@192.168.1.2:9418/Notes".to_string(),
        endpoint_id: None,
    })
    .unwrap();
    assert_eq!(target.id, SecretKey::from_bytes(&[7u8; 32]).public());
}

